"342 :   @Override
343 :   protected List<PassFactory> getOptimizations() {
344 :     List<PassFactory> passes = Lists.newArrayList();
345 :     passes.add(garbageCollectChecks);
346 : 
347 :     // TODO(nicksantos): The order of these passes makes no sense, and needs
348 :     // to be re-arranged.
349 : 
350 :     if (options.runtimeTypeCheck) {
351 :       passes.add(runtimeTypeCheck);
352 :     }
353 : 
354 :     passes.add(createEmptyPass("beforeStandardOptimizations"));
355 : 
356 :     if (options.replaceIdGenerators) {
357 :       passes.add(replaceIdGenerators);
358 :     }
359 : 
360 :     // Optimizes references to the arguments variable.
361 :     if (options.optimizeArgumentsArray) {
362 :       passes.add(optimizeArgumentsArray);
363 :     }
364 : 
365 :     // Abstract method removal works best on minimally modified code, and also
366 :     // only needs to run once.
367 :     if (options.closurePass &&
368 :         (options.removeAbstractMethods || options.removeClosureAsserts)) {
369 :       passes.add(closureCodeRemoval);
370 :     }
371 : 
372 :     // Collapsing properties can undo constant inlining, so we do this before
373 :     // the main optimization loop.
374 :     if (options.collapseProperties) {
375 :       passes.add(collapseProperties);
376 :     }
377 : 
378 :     // ReplaceStrings runs after CollapseProperties in order to simplify
379 :     // pulling in values of constants defined in enums structures.
380 :     if (!options.replaceStringsFunctionDescriptions.isEmpty()) {
381 :       passes.add(replaceStrings);
382 :     }
383 : 
384 :     // Tighten types based on actual usage.
385 :     if (options.tightenTypes) {
386 :       passes.add(tightenTypesBuilder);
387 :     }
388 : 
389 :     // Property disambiguation should only run once and needs to be done
390 :     // soon after type checking, both so that it can make use of type
391 :     // information and so that other passes can take advantage of the renamed
392 :     // properties.
393 :     if (options.disambiguateProperties) {
394 :       passes.add(disambiguateProperties);
395 :     }
396 : 
397 :     if (options.computeFunctionSideEffects) {
398 :       passes.add(markPureFunctions);
399 :     } else if (options.markNoSideEffectCalls) {
400 :       // TODO(user) The properties that this pass adds to CALL and NEW
401 :       // AST nodes increase the AST's in-memory size.  Given that we are
402 :       // already running close to our memory limits, we could run into
403 :       // trouble if we end up using the @nosideeffects annotation a lot
404 :       // or compute @nosideeffects annotations by looking at function
405 :       // bodies.  It should be easy to propagate @nosideeffects
406 :       // annotations as part of passes that depend on this property and
407 :       // store the result outside the AST (which would allow garbage
408 :       // collection once the pass is done).
409 :       passes.add(markNoSideEffectCalls);
410 :     }
411 : 
412 :     if (options.chainCalls) {
413 :       passes.add(chainCalls);
414 :     }
415 : 
416 :     // Constant checking must be done after property collapsing because
417 :     // property collapsing can introduce new constants (e.g. enum values).
418 :     // TODO(johnlenz): make checkConsts namespace aware so it can be run
419 :     // as during the checks phase.
420 :     passes.add(checkConsts);
421 : 
422 :     // The Caja library adds properties to Object.prototype, which breaks
423 :     // most for-in loops.  This adds a check to each loop that skips
424 :     // any property matching /___$/.
425 :     if (options.ignoreCajaProperties) {
426 :       passes.add(ignoreCajaProperties);
427 :     }
428 : 
429 :     assertAllOneTimePasses(passes);
430 : 
431 :     if (options.smartNameRemoval || options.reportPath != null) {
432 :       passes.addAll(getCodeRemovingPasses());
433 :       passes.add(smartNamePass);
434 :     }
435 : 
436 :     // This needs to come after the inline constants pass, which is run within
437 :     // the code removing passes.
438 :     if (options.closurePass) {
439 :       passes.add(closureOptimizePrimitives);
440 :     }
441 : 
442 :     // TODO(user): This forces a first crack at crossModuleCodeMotion
443 :     // before devirtualization. Once certain functions are devirtualized,
444 :     // it confuses crossModuleCodeMotion ability to recognized that
445 :     // it is recursive.
446 : 
447 :     // TODO(user): This is meant for a temporary quick win.
448 :     // In the future, we might want to improve our analysis in
449 :     // CrossModuleCodeMotion so we don't need to do this.
450 :     if (options.crossModuleCodeMotion) {
451 :       passes.add(crossModuleCodeMotion);
452 :     }
453 : 
454 :     // Method devirtualization benefits from property disambiguation so
455 :     // it should run after that pass but before passes that do
456 :     // optimizations based on global names (like cross module code motion
457 :     // and inline functions).  Smart Name Removal does better if run before
458 :     // this pass.
459 :     if (options.devirtualizePrototypeMethods) {
460 :       passes.add(devirtualizePrototypeMethods);
461 :     }
462 : 
463 :     if (options.customPasses != null) {
464 :       passes.add(getCustomPasses(
465 :           CustomPassExecutionTime.BEFORE_OPTIMIZATION_LOOP));
466 :     }
467 : 
468 :     passes.add(createEmptyPass("beforeMainOptimizations"));
469 : 
470 :     if (options.specializeInitialModule) {
471 :       // When specializing the initial module, we want our fixups to be
472 :       // as lean as possible, so we run the entire optimization loop to a
473 :       // fixed point before specializing, then specialize, and then run the
474 :       // main optimization loop again.
475 : 
476 :       passes.addAll(getMainOptimizationLoop());
477 : 
478 :       if (options.crossModuleCodeMotion) {
479 :         passes.add(crossModuleCodeMotion);
480 :       }
481 : 
482 :       if (options.crossModuleMethodMotion) {
483 :         passes.add(crossModuleMethodMotion);
484 :       }
485 : 
486 :       passes.add(specializeInitialModule.makeOneTimePass());
487 :     }
488 : 
489 :     passes.addAll(getMainOptimizationLoop());
490 : 
491 :     passes.add(createEmptyPass("beforeModuleMotion"));
492 : 
493 :     if (options.crossModuleCodeMotion) {
494 :       passes.add(crossModuleCodeMotion);
495 :     }
496 : 
497 :     if (options.crossModuleMethodMotion) {
498 :       passes.add(crossModuleMethodMotion);
499 :     }
500 : 
501 :     passes.add(createEmptyPass("afterModuleMotion"));
502 : 
503 :     // Some optimizations belong outside the loop because running them more
504 :     // than once would either have no benefit or be incorrect.
505 :     if (options.customPasses != null) {
506 :       passes.add(getCustomPasses(
507 :           CustomPassExecutionTime.AFTER_OPTIMIZATION_LOOP));
508 :     }
509 : 
510 :     if (options.flowSensitiveInlineVariables) {
511 :       passes.add(flowSensitiveInlineVariables);
512 : 
513 :       // After inlining some of the variable uses, some variables are unused.
514 :       // Re-run remove unused vars to clean it up.
515 :       if (options.removeUnusedVars || options.removeUnusedLocalVars) {
516 :         passes.add(removeUnusedVars);
517 :       }
518 :     }
519 : 
520 :     // Running this pass again is required to have goog.events compile down to
521 :     // nothing when compiled on its own.
522 :     if (options.smartNameRemoval) {
523 :       passes.add(smartNamePass2);
524 :     }
525 : 
526 :     if (options.collapseAnonymousFunctions) {
527 :       passes.add(collapseAnonymousFunctions);
528 :     }
529 : 
530 :     // Move functions before extracting prototype member declarations.
531 :     if (options.moveFunctionDeclarations ||
532 :         // renamePrefixNamescape relies on moveFunctionDeclarations
533 :         // to preserve semantics.
534 :         options.renamePrefixNamespace != null) {
535 :       passes.add(moveFunctionDeclarations);
536 :     }
537 : 
538 :     if (options.anonymousFunctionNaming ==
539 :         AnonymousFunctionNamingPolicy.MAPPED) {
540 :       passes.add(nameMappedAnonymousFunctions);
541 :     }
542 : 
543 :     // The mapped name anonymous function pass makes use of information that
544 :     // the extract prototype member declarations pass removes so the former
545 :     // happens before the latter.
546 :     //
547 :     // Extracting prototype properties screws up the heuristic renaming
548 :     // policies, so never run it when those policies are requested.
549 :     if (options.extractPrototypeMemberDeclarations &&
550 :         (options.propertyRenaming != PropertyRenamingPolicy.HEURISTIC &&
551 :          options.propertyRenaming !=
552 :             PropertyRenamingPolicy.AGGRESSIVE_HEURISTIC)) {
553 :       passes.add(extractPrototypeMemberDeclarations);
554 :     }
555 : 
556 :     if (options.ambiguateProperties &&
557 :         (options.propertyRenaming == PropertyRenamingPolicy.ALL_UNQUOTED)) {
558 :       passes.add(ambiguateProperties);
559 :     }
560 : 
561 :     if (options.propertyRenaming != PropertyRenamingPolicy.OFF) {
562 :       passes.add(renameProperties);
563 :     }
564 : 
565 :     // Reserve global names added to the "windows" object.
566 :     if (options.reserveRawExports) {
567 :       passes.add(gatherRawExports);
568 :     }
569 : 
570 :     // This comes after property renaming because quoted property names must
571 :     // not be renamed.
572 :     if (options.convertToDottedProperties) {
573 :       passes.add(convertToDottedProperties);
574 :     }
575 : 
576 :     // Property renaming must happen before this pass runs since this
577 :     // pass may convert dotted properties into quoted properties.  It
578 :     // is beneficial to run before alias strings, alias keywords and
579 :     // variable renaming.
580 :     if (options.rewriteFunctionExpressions) {
581 :       passes.add(rewriteFunctionExpressions);
582 :     }
583 : 
584 :     // This comes after converting quoted property accesses to dotted property
585 :     // accesses in order to avoid aliasing property names.
586 :     if (!options.aliasableStrings.isEmpty() || options.aliasAllStrings) {
587 :       passes.add(aliasStrings);
588 :     }
589 : 
590 :     if (options.aliasExternals) {
591 :       passes.add(aliasExternals);
592 :     }
593 : 
594 :     if (options.aliasKeywords) {
595 :       passes.add(aliasKeywords);
596 :     }
597 : 
598 :     // Passes after this point can no longer depend on normalized AST
599 :     // assumptions.
600 :     passes.add(markUnnormalized);
601 : 
602 :     if (options.coalesceVariableNames) {
603 :       passes.add(coalesceVariableNames);
604 : 
605 :       // coalesceVariables creates identity assignments and more redundant code
606 :       // that can be removed, rerun the peephole optimizations to clean them
607 :       // up.
608 :       if (options.foldConstants) {
609 :         passes.add(peepholeOptimizations);
610 :       }
611 :     }
612 : 
613 :     if (options.collapseVariableDeclarations) {
614 :       passes.add(exploitAssign);
615 :       passes.add(collapseVariableDeclarations);
616 :     }
617 : 
618 :     // This pass works best after collapseVariableDeclarations.
619 :     passes.add(denormalize);
620 : 
621 :     if (options.instrumentationTemplate != null) {
622 :       passes.add(instrumentFunctions);
623 :     }
624 : 
625 :     if (options.variableRenaming != VariableRenamingPolicy.ALL) {
626 :       // If we're leaving some (or all) variables with their old names,
627 :       // then we need to undo any of the markers we added for distinguishing
628 :       // local variables ("$$1").
629 :       passes.add(invertContextualRenaming);
630 :     }
631 : 
632 :     if (options.variableRenaming != VariableRenamingPolicy.OFF) {
633 :       passes.add(renameVars);
634 :     }
635 : 
636 :     if (options.groupVariableDeclarations) {
637 :       passes.add(groupVariableDeclarations);
638 :     }
639 : 
640 :     // This pass should run after names stop changing.
641 :     if (options.processObjectPropertyString) {
642 :       passes.add(objectPropertyStringPostprocess);
643 :     }
644 : 
645 :     if (options.labelRenaming) {
646 :       passes.add(renameLabels);
647 :     }
648 : 
649 :     if (options.foldConstants) {
650 :       passes.add(latePeepholeOptimizations);
651 :     }
652 : 
653 :     if (options.anonymousFunctionNaming ==
654 :         AnonymousFunctionNamingPolicy.UNMAPPED) {
655 :       passes.add(nameUnmappedAnonymousFunctions);
656 :     }
657 : 
658 :     if (options.renamePrefixNamespace != null) {
659 :       if (!GLOBAL_SYMBOL_NAMESPACE_PATTERN.matcher(
660 :           options.renamePrefixNamespace).matches()) {
661 :         throw new IllegalArgumentException(
662 :             "Illegal character in renamePrefixNamespace name: "
663 :             + options.renamePrefixNamespace);
664 :       }
665 :       passes.add(rescopeGlobalSymbols);
666 :     }
667 : 
668 :     passes.add(stripSideEffectProtection);
669 : 
670 :     // Safety checks
671 :     passes.add(sanityCheckAst);
672 :     passes.add(sanityCheckVars);
673 : 
674 :     return passes;
675 :   }"

