"53 :   public void setOptionsForCompilationLevel(CompilerOptions options) {
54 :     switch (this) {
55 :       case WHITESPACE_ONLY:
56 :         applyBasicCompilationOptions(options);
57 :         break;
58 :       case SIMPLE_OPTIMIZATIONS:
59 :         applySafeCompilationOptions(options);
60 :         break;
61 :       case ADVANCED_OPTIMIZATIONS:
62 :         applyFullCompilationOptions(options);
63 :         break;
64 :       default:
65 :         throw new RuntimeException("Unknown compilation level.");
66 :     }
