" 95 :   private static void applySafeCompilationOptions(CompilerOptions options) {
 96 :     // ReplaceIdGenerators is on by default, but should run in simple mode.
 97 :     options.replaceIdGenerators = false;
 98 : 
 99 :     // Does not call applyBasicCompilationOptions(options) because the call to
100 :     // skipAllCompilerPasses() cannot be easily undone.
101 :     options.dependencyOptions.setDependencySorting(true);
102 :     options.closurePass = true;
103 :     options.setRenamingPolicy(
104 :         VariableRenamingPolicy.LOCAL, PropertyRenamingPolicy.OFF);
105 :     options.shadowVariables = true;
106 :     options.setInlineVariables(Reach.LOCAL_ONLY);
107 :     options.flowSensitiveInlineVariables = true;
108 :     options.setInlineFunctions(Reach.LOCAL_ONLY);
109 :     options.setAssumeClosuresOnlyCaptureReferences(true);
110 :     options.checkGlobalThisLevel = CheckLevel.OFF;
111 :     options.foldConstants = true;
112 :     options.coalesceVariableNames = true;
113 :     options.deadAssignmentElimination = true;
114 :     options.collapseVariableDeclarations = true;
115 :     options.convertToDottedProperties = true;
116 :     options.labelRenaming = true;
117 :     options.removeDeadCode = true;
118 :     options.optimizeArgumentsArray = true;
119 :     options.setRemoveUnusedVariables(Reach.LOCAL_ONLY);
120 :     options.collapseObjectLiterals = true;
121 :     options.protectHiddenSideEffects = true;
122 : 
123 :     // Allows annotations that are not standard.
124 :     options.setWarningLevel(DiagnosticGroups.NON_STANDARD_JSDOC,
125 :         CheckLevel.OFF);
126 :   }"

